import{_ as i,o as l,c as e,a8 as t}from"./chunks/framework.BppdKxCY.js";const p=JSON.parse('{"title":"EP.66 3D 场景里的孪生兄弟","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.66-3d-digital-twin.md","filePath":"comics/EP.66-3d-digital-twin.md","lastUpdated":1793706365000}'),o={name:"comics/EP.66-3d-digital-twin.md"};function s(r,a,n,d,c,h){return l(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="ep-66-3d-场景里的孪生兄弟" tabindex="-1">EP.66 3D 场景里的孪生兄弟 <a class="header-anchor" href="#ep-66-3d-场景里的孪生兄弟" aria-label="Permalink to &quot;EP.66 3D 场景里的孪生兄弟&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../92-3d-digital-twin">92-3d-digital-twin.md</a>（92.1 场景图 / 92.2 射线拾取 / 92.4 数字孪生）· 示例：<code>examples/92-01-3d-digital-twin.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：3D 场景点击设备没反应——3D 物体不是 DOM，没有 onclick。</li><li><strong>第 2 格</strong>：码叔揭秘射线拾取——从相机发射射线，命中哪个物体就是点中了谁。</li><li><strong>第 3 格</strong>：像素酱实证数字孪生数据绑定——传感器数据驱动 Mesh 的颜色/高度/透明度。</li><li><strong>第 4 格</strong>：码叔结案——GIS 坐标转换 + InstancedMesh 降 Draw Call。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-3d-交互的特殊性" tabindex="-1">第 1 格 · 3D 交互的特殊性 <a class="header-anchor" href="#第-1-格-·-3d-交互的特殊性" aria-label="Permalink to &quot;第 1 格 · 3D 交互的特殊性&quot;">​</a></h3><ul><li>3D 物体渲染在 Canvas 上，不是 DOM 元素；</li><li>没有原生点击事件，需要自己实现拾取；</li><li>核心工具：<code>THREE.Raycaster</code>。</li></ul><h3 id="第-2-格-·-射线拾取-raycaster" tabindex="-1">第 2 格 · 射线拾取（Raycaster） <a class="header-anchor" href="#第-2-格-·-射线拾取-raycaster" aria-label="Permalink to &quot;第 2 格 · 射线拾取（Raycaster）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>鼠标屏幕坐标 → NDC(-1~1) → setFromCamera → intersectObjects</span></span></code></pre></div><ul><li>从相机位置沿鼠标方向发射射线；</li><li>与场景物体的包围盒/三角面求交；</li><li>返回按距离排序的命中列表，<code>hits[0]</code> 就是点中的物体。</li></ul><h3 id="第-3-格-·-数字孪生数据绑定" tabindex="-1">第 3 格 · 数字孪生数据绑定 <a class="header-anchor" href="#第-3-格-·-数字孪生数据绑定" aria-label="Permalink to &quot;第 3 格 · 数字孪生数据绑定&quot;">​</a></h3><ul><li>建立&quot;设备 ID → Mesh&quot;映射；</li><li>WebSocket 推送实时数据，更新 Mesh 属性： <ul><li>温度 → 材质颜色（冷蓝→热红）</li><li>功率 → 高度（scale.y）</li><li>状态 → 透明度（在线/离线/告警）</li></ul></li></ul><h3 id="第-4-格-·-gis-坐标与性能" tabindex="-1">第 4 格 · GIS 坐标与性能 <a class="header-anchor" href="#第-4-格-·-gis-坐标与性能" aria-label="Permalink to &quot;第 4 格 · GIS 坐标与性能&quot;">​</a></h3><ul><li>经纬度转局部坐标：1°纬度≈111km，经度×cos(lat)；</li><li>InstancedMesh：N 个相同物体 1 次 Draw Call；</li><li>LOD：远距低模、近距高模；</li><li>切换场景时 dispose 几何体和材质防内存泄漏。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../92-3d-digital-twin#_92-7-本章避坑清单">《92.7 本章避坑清单》</a></p></blockquote><ol><li>点击不准 → 用 NDC 坐标转换，注意递归参数；</li><li>模型全黑 → 没加光照，MeshStandardMaterial 需要光源；</li><li>内存泄漏 → 移除物体时 dispose 几何体/材质/纹理。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>3D 场景点击物体的核心原理是什么？——<strong>射线拾取：从相机发射射线与物体求交</strong>。</li><li>数字孪生如何让 3D 模型&quot;活&quot;起来？——<strong>建立设备 ID→Mesh 映射，实时数据更新 Mesh 属性（颜色/高度/透明度）</strong>。</li><li>经纬度转场景坐标时，经度为什么要乘 cos(lat)？——<strong>因为经线在高纬度收敛，1°经度的实际距离随纬度增大而缩短</strong>。</li></ol>',19)])])}const g=i(o,[["render",s]]);export{p as __pageData,g as default};
